## Converting GPX to JSON in Python

GPX (GPS Exchange Format) is an XML-based format for storing GPS data. Here's how to convert GPX files to JSON in Python.

### Installation

First, install the required library:

```bash
pip install gpxpy
```

---

### Basic GPX to JSON Conversion

```python
import gpxpy
import json

# Parse GPX file
with open('track.gpx', 'r') as gpx_file:
    gpx = gpxpy.parse(gpx_file)

# Convert to dictionary
gpx_data = {
    'tracks': [],
    'waypoints': [],
    'routes': []
}

# Extract track data
for track in gpx.tracks:
    track_data = {
        'name': track.name,
        'segments': []
    }
    for segment in track.segments:
        segment_data = {
            'points': []
        }
        for point in segment.points:
            segment_data['points'].append({
                'latitude': point.latitude,
                'longitude': point.longitude,
                'elevation': point.elevation,
                'time': str(point.time)
            })
        track_data['segments'].append(segment_data)
    gpx_data['tracks'].append(track_data)

# Extract waypoints
for waypoint in gpx.waypoints:
    gpx_data['waypoints'].append({
        'name': waypoint.name,
        'latitude': waypoint.latitude,
        'longitude': waypoint.longitude,
        'elevation': waypoint.elevation
    })

# Convert to JSON
json_output = json.dumps(gpx_data, indent=4)
print(json_output)
```

---

### Sample Output

```json
{
    "tracks": [
        {
            "name": "Morning Run",
            "segments": [
                {
                    "points": [
                        {
                            "latitude": 37.7749,
                            "longitude": -122.4194,
                            "elevation": 52.0,
                            "time": "2023-01-01 08:00:00"
                        },
                        {
                            "latitude": 37.7750,
                            "longitude": -122.4180,
                            "elevation": 55.0,
                            "time": "2023-01-01 08:01:00"
                        }
                    ]
                }
            ]
        }
    ],
    "waypoints": [],
    "routes": []
}
```

---

### Save JSON to File

```python
import gpxpy
import json

def gpx_to_json(gpx_file_path, json_file_path):
    with open(gpx_file_path, 'r') as gpx_file:
        gpx = gpxpy.parse(gpx_file)

    gpx_data = {'tracks': [], 'waypoints': [], 'routes': []}

    for track in gpx.tracks:
        track_info = {'name': track.name, 'segments': []}
        for segment in track.segments:
            points = [
                {
                    'lat': p.latitude,
                    'lon': p.longitude,
                    'ele': p.elevation,
                    'time': str(p.time)
                }
                for p in segment.points
            ]
            track_info['segments'].append({'points': points})
        gpx_data['tracks'].append(track_info)

    # Save to JSON file
    with open(json_file_path, 'w') as json_file:
        json.dump(gpx_data, json_file, indent=4)

    print(f"Successfully converted {gpx_file_path} to {json_file_path}")
    return gpx_data

# Usage
result = gpx_to_json('input.gpx', 'output.json')
```

---

### Output

```
Successfully converted input.gpx to output.json
```

---

### Using xml.etree for Manual Parsing (No External Library)

```python
import xml.etree.ElementTree as ET
import json

def parse_gpx_manual(gpx_file):
    tree = ET.parse(gpx_file)
    root = tree.getroot()

    namespace = {'gpx': 'http://www.topografix.com/GPX/1/1'}

    gpx_data = {'waypoints': [], 'tracks': []}

    # Parse waypoints
    for wpt in root.findall('gpx:wpt', namespace):
        gpx_data['waypoints'].append({
            'lat': wpt.get('lat'),
            'lon': wpt.get('lon'),
            'name': wpt.findtext('gpx:name', default='', namespaces=namespace)
        })

    # Parse tracks
    for trk in root.findall('gpx:trk', namespace):
        track = {'name': trk.findtext('gpx:name', default='', namespaces=namespace), 'points': []}
        for trkpt in trk.findall('.//gpx:trkpt', namespace):
            track['points'].append({
                'lat': trkpt.get('lat'),
                'lon': trkpt.get('lon'),
                'ele': trkpt.findtext('gpx:ele', default='0', namespaces=namespace)
            })
        gpx_data['tracks'].append(track)

    return json.dumps(gpx_data, indent=4)

print(parse_gpx_manual('track.gpx'))
```

### Output

```json
{
    "waypoints": [
        {
            "lat": "37.7749",
            "lon": "-122.4194",
            "name": "Start Point"
        }
    ],
    "tracks": [
        {
            "name": "Trail Route",
            "points": [
                {
                    "lat": "37.7749",
                    "lon": "-122.4194",
                    "ele": "52.0"
                }
            ]
        }
    ]
}
```

---

### Key Points

| Method | Library | Best For |
|--------|---------|----------|
| `gpxpy` | External | Easy parsing with full feature support |
| `xml.etree` | Built-in | Lightweight, no dependencies |
| `json.dumps()` | Built-in | Converting dict to JSON string |
| `json.dump()` | Built-in | Writing JSON directly to file |

